#include <vector>
#include <iostream>

int main() {
    // Value initialization: all 5 elements are zero
    std::vector<int> v1(5);
    std::cout << v1[0] << " " << v1[4] << std::endl; // Output: 0 0

    struct S { int x; S() : x(99) {} };
    // Default construction: all 3 elements have x=99
    std::vector<S> v2(3);
    std::cout << v2[0].x << std::endl; // Output: 99
}
